<?php namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest; class UpdateEventRequest extends FormRequest {public function authorize():bool{return $this->user()?->role?->value==='organizer'&&$this->route('event')->organizer_id===$this->user()->id;}public function rules():array{return ['title'=>['sometimes','string','max:180'],'description'=>['nullable','string'],'city'=>['sometimes','string'],'category'=>['sometimes','string'],'starts_at'=>['sometimes','date','after:now'],'status'=>['sometimes','in:draft,published,postponed'],'max_per_order'=>['sometimes','integer','min:1','max:20']];}public function messages():array{return ['title.required'=>'اسم الفعالية مطلوب.'];}}
